uniform float amzp_coreGlow;
uniform float amzp_colorMode;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_overdrawOn;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxs) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position * pxs;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 0) o = f;
        else if (int(amzp_blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(amzp_blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(amzp_blendMode) == 4) o = float4(b.rgb + f.rgb, max(b.a, f.a));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float4 nmLight(float3 L) { L = max(L, 0.0); return float4(clamp(L, 0.0, 1.0), clamp(max(L.r, max(L.g, L.b)), 0.0, 1.0)); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.1) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float4 layerAt(float2 uv) { return inside(uv) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float3 hue(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float3 thr(float4 c) {
        if (c.a <= 0.0001) return float3(0.0);
        float3 u = c.rgb / c.a;
        float th = clamp(amzp_threshold, 0.0, 0.999);
        float w = max(dot(u, float3(0.299, 0.587, 0.114)) - th, 0.0) / (1.0 - th);
        return (int(amzp_colorMode) == 0 ? u : float3(1.0)) * w * c.a;
    }
    void nmMain() {
        float2 uv = amzScreenNorm();
        if (amzPass == 0) {
            float2 ts = 1.0 / (screen.zw/1.0);
            float3 m = float3(0.0);
            for (int j = 0; j < 4; j++) for (int i = 0; i < 4; i++) {
                float3 c = thr(amzTexture(0, uv + (float2(float(i), float(j)) - 1.5) * ts));
                if (dot(c, float3(1.0)) > dot(m, float3(1.0))) m = c;
            }
            amzOutput = float4(sqrt(clamp(m, 0.0, 1.0)), 1.0);
            return;
        }
        float4 orig = amzTexture(0, uv);
        float2 S = screen.zw;
        uv -= float2(amzp_position.x, -amzp_position.y) * pxs() / S;
        float2 st = max(amzp_stretch, float2(0.01));
        float Lr = max(amzp_rayLength, 1.0) * pxs() * max(amzp_scale * 2.0, 0.002);
        float lines = int(amzp_rays) == 0 ? 2.0 : (int(amzp_rays) == 2 ? 4.0 : 3.0);
        float rot = radians(amzp_rotation + amzp_angle) + prog(0.0) * 6.2831853;
        float ex = 1.0 + clamp(amzp_falloff, 0.0, 1.0) * 5.0;
        float n = clamp(floor(Lr * max(st.x, st.y) / 3.0), 6.0, 48.0);
        float3 acc = float3(0.0);
        for (int k = 0; k < 4; k++) {
            float fk = float(k);
            if (fk >= lines) break;
            float a = rot + fk * 3.14159265 / lines;
            float2 dir = float2(cos(a), sin(a)) * st / S;
            for (int j = 1; j <= 48; j++) {
                float fj = float(j);
                if (fj > n) break;
                float s = fj / n;
                float w = pow(1.0 - s, ex);
                float3 col = int(amzp_colorMode) == 2 ? hue(fract(s * 0.85 + fk * 0.13)) * 1.4 : float3(1.0);
                float3 g1 = amzTexture(1, uv + dir * s * Lr).rgb;
                float3 g2 = amzTexture(1, uv - dir * s * Lr).rgb;
                acc += (g1 * g1 + g2 * g2) * w * col;
            }
        }
        float3 core = amzTexture(1, uv).rgb;
        float3 L = acc * (6.0 / n) + core * core * amzp_coreGlow * 2.0;
        L *= max(amzp_brightness, 0.0);
        amzOutput = nmBlend(orig, nmGradMap(nmLight(L)));
    }
    void amzRender() {
        if ((amzp_safeRender>0.5)) { amzOutput = amzTexture(0, amzScreenNorm()); return; }
        nmMain();
        if (!(amzp_overdrawOn>0.5) && amzPass >= 1) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
